import type { Metadata } from "next";
import { event, siteUrl } from "@/config/event";

/** Default share card, generated by src/app/opengraph-image.tsx. */
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${event.shortName}: ${event.dates.display}, ${event.city}, ${event.country}`,
};

export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  const url = `${siteUrl}${path === "/" ? "" : path}`;
  // Page titles that already name the event (the home page) are not suffixed again.
  const shareTitle = title.includes(event.shortName) ? title : `${title} | ${event.shortName}`;
  return {
    title,
    description,
    alternates: { canonical: url || siteUrl },
    openGraph: {
      title: shareTitle,
      description,
      url: url || siteUrl,
      siteName: event.shortName,
      locale: "en_GH",
      type: "website",
      images: [shareImage],
    },
    twitter: { card: "summary_large_image", title: shareTitle, description, images: [shareImage] },
  };
}

/** schema.org structured data for the Ghana event. Venue omitted until confirmed. */
export function eventJsonLd() {
  const location =
    event.venue.status === "confirmed" && event.venue.name
      ? {
          "@type": "Place",
          name: event.venue.name,
          address: { "@type": "PostalAddress", streetAddress: event.venue.address ?? undefined, addressLocality: event.city, addressCountry: "GH" },
        }
      : {
          "@type": "Place",
          name: `${event.city}, ${event.country} (venue to be announced)`,
          address: { "@type": "PostalAddress", addressLocality: event.city, addressRegion: "Greater Accra", addressCountry: "GH" },
        };
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": `${siteUrl}/#organiser`,
        name: event.organisers.ghana.name,
        url: event.organisers.ghana.url,
        logo: `${siteUrl}/images/brand/makersplace.png`,
        email: event.contact.email,
        telephone: event.contact.phones[0],
        contactPoint: [
          { "@type": "ContactPoint", contactType: "Partnerships", email: event.contact.partnershipsEmail, telephone: event.contact.phones, areaServed: "GH" },
        ],
      },
      {
        "@type": "WebSite",
        "@id": `${siteUrl}/#website`,
        url: siteUrl,
        name: event.shortName,
        publisher: { "@id": `${siteUrl}/#organiser` },
        inLanguage: "en",
      },
      {
        "@type": "SportsEvent",
        "@id": `${siteUrl}/#event`,
        name: event.name,
        description: event.description,
        sport: "Robotics",
        startDate: event.dates.start,
        endDate: event.dates.end,
        // Moved from 29–30 January 2027 (announced earlier), so search engines replace the old dates.
        eventStatus: "https://schema.org/EventRescheduled",
        previousStartDate: "2027-01-29",
        eventAttendanceMode: "https://schema.org/OfflineEventAttendanceMode",
        location,
        image: [`${siteUrl}/opengraph-image`, `${siteUrl}/images/hero-robotics-lab.jpg`],
        audience: { "@type": "EducationalAudience", educationalRole: "student", audienceType: "Students aged 10 and over, schools and robotics clubs" },
        organizer: { "@id": `${siteUrl}/#organiser` },
        url: siteUrl,
      },
    ],
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      item: `${siteUrl}${it.path}`,
    })),
  };
}
